package dev.musicstudio.song;

import dev.musicstudio.blueprint.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class BlueprintCompilerTest {
    static SongProject tune(boolean loop){SongProject s=SongProject.legacyDemo();s.clips.clear();s.channels=new ArrayList<>(List.of(s.channels.get(2)));s.patterns.clear();var p=new SongProject.Pattern("test",1);p.length=SongProject.PPQ*4;p.notes.getFirst().add(new SongProject.Note(0,1,66,127));p.notes.getFirst().add(new SongProject.Note(1,1,69,127));s.patterns.add(p);s.endPpq=SongProject.PPQ*4;s.clips.add(new SongProject.Clip(0,0,0,1));s.loop=loop;return s;}
    @Test void nativeAbsoluteTimingTrimsUnusedProjectTail(){var b=MusicBlueprint.compile(tune(false));assertEquals(6,b.period());assertEquals(0,b.notes().getFirst().tick());assertEquals(2,b.notes().get(1).tick());assertEquals(25,b.maxErrorMs(),.001);assertEquals(2,b.outputs().size());}
    @Test void onlyVanillaPlaybackPartsAndButtonAreProduced(){var b=MusicBlueprint.compile(tune(false));assertTrue(b.parts().stream().anyMatch(p->p.pos().equals(b.lever())&&p.block().equals("stone_button")));assertTrue(b.parts().stream().noneMatch(p->p.block().equals("lever")));assertTrue(b.parts().stream().anyMatch(p->p.block().equals("repeater")));assertEquals(b.parts().size(),b.parts().stream().map(MusicBlueprint.Part::pos).distinct().count());assertTrue(b.parts().stream().allMatch(p->!p.block().contains(":")));assertEquals(2,b.parts().stream().filter(p->p.block().equals("note_block")).count());}
    @Test void snapshotsAreDetachedAndRejectCorruption(){var s=tune(false);var bytes=BlueprintData.pack(s);String original=ProjectStore.encode(s);s.title="changed";assertEquals(original,ProjectStore.encode(BlueprintData.unpack(bytes)));assertThrows(StudioException.class,()->BlueprintData.unpack(new byte[]{1,2,3}));}
    @Test void arbitrarySamplesRequireExplicitCommandExport(){var s=tune(false);s.channels.getFirst().sound="minecraft:ambient.cave";var error=assertThrows(StudioException.class,()->MusicBlueprint.compile(s));assertEquals("error.vanilla_sample",error.key);s.commandSamples=true;var b=MusicBlueprint.compile(s);assertEquals(2,b.parts().stream().filter(p->p.block().equals("command_block")).count());assertTrue(b.parts().stream().filter(p->p.block().equals("command_block")).allMatch(p->p.command().startsWith("playsound minecraft:ambient.cave record ")));}
    @Test void loopAddsRealComparatorFeedbackAndHasFourTickPeriod(){var s=tune(false);var once=MusicBlueprint.compile(s);s.loop=true;var loop=MusicBlueprint.compile(s);assertTrue(loop.parts().stream().anyMatch(p->p.pos().equals(loop.lever())&&p.block().equals("lever")));assertTrue(loop.parts().stream().noneMatch(p->p.block().equals("stone_button")));assertTrue(loop.parts().size()>once.parts().size());assertTrue(loop.parts().stream().anyMatch(p->p.block().equals("comparator")&&p.value()==1));assertEquals(0,loop.period()%4);assertTrue(loop.parts().stream().filter(p->p.block().equals("repeater")).allMatch(p->p.value()>=1&&p.value()<=4));}
    @Test void hardSpaceAndRotationLimitsAreEnforced(){var s=tune(false);s.maxX=3;s.maxY=3;s.maxZ=3;var rejected=s;assertThrows(StudioException.class,()->MusicBlueprint.compile(rejected));s=tune(false);s.maxX=48;s.maxZ=12;var b=MusicBlueprint.compile(s);assertTrue(b.fitsRotation(0));assertEquals(b.z()<=s.maxX&&b.x()<=s.maxZ,b.fitsRotation(1));for(int r=0;r<4;r++)for(var p:b.parts()){var c=b.rotate(p.pos(),r);assertTrue(c.x()>=0&&c.x()<b.width(r)&&c.z()>=0&&c.z()<b.depth(r));}}
    @Test void demoHybridPreviewFitsDefaultLimitsWithSamplesMuted(){var s=SongProject.legacyDemo();s.channels.get(6).muted=true;s.channels.get(7).muted=true;var b=MusicBlueprint.preview(s);assertTrue(b.x()<=s.maxX&&b.y()<=s.maxY&&b.z()<=s.maxZ);assertEquals(640,b.period());}
    @Test void emptyAndExcessiveChordsFailClearly(){var s=tune(false);s.clips.clear();var rejected=s;assertThrows(StudioException.class,()->MusicBlueprint.compile(rejected));s=tune(false);var list=s.patterns.getFirst().notes.getFirst();list.clear();for(int i=0;i<17;i++)list.add(new SongProject.Note(0,1,66,127));var candidate=s;assertEquals("error.vanilla_chord",assertThrows(StudioException.class,()->MusicBlueprint.compile(candidate)).key);}
}
